import { useAuth } from "@/_core/hooks/useAuth";
import { startLogin } from "@/const";
import { AIChatBox, type Message } from "@/components/AIChatBox";
import { trpc } from "@/lib/trpc";
import {
  Activity,
  AlertTriangle,
  ArrowRight,
  Boxes,
  Check,
  CheckCircle2,
  ChevronRight,
  CircleDot,
  Cloud,
  Code2,
  Copy,
  Cpu,
  Download,
  ExternalLink,
  FileCode2,
  Globe2,
  Hammer,
  LayoutDashboard,
  LifeBuoy,
  Loader2,
  LockKeyhole,
  LogOut,
  Menu,
  MoreHorizontal,
  Package,
  PanelLeft,
  Play,
  Plus,
  Rocket,
  Search,
  Send,
  Settings2,
  Sparkles,
  Smartphone,
  Terminal,
  Wand2,
  X,
  Zap,
} from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useLocation } from "wouter";

type Blueprint = {
  summary: string;
  pages: string[];
  tables: string[];
  roles: string[];
  checklist: string[];
};

type Diagnosis = {
  id: number;
  summary: string;
  confidence: number;
  affectedArea: string;
  steps: string[];
  patches?: Array<{ path: string; reason: string }>;
};

type View = "dashboard" | "templates" | "preview" | "domains" | "publishing" | "mobile";

const navItems: { label: string; path: string; icon: typeof LayoutDashboard }[] = [
  { label: "Overview", path: "/", icon: LayoutDashboard },
  { label: "Templates", path: "/templates", icon: Boxes },
  { label: "Preview & Fix", path: "/preview", icon: Play },
  { label: "Domains", path: "/domains", icon: Globe2 },
  { label: "Publishing", path: "/publishing", icon: Rocket },
  { label: "Android builds", path: "/mobile-builds", icon: Smartphone },
];

const templateFallback = [
  { id: 1, slug: "school", name: "School OS", category: "Education", description: "Admissions, classes and parent updates in one calm workspace.", accent: "#8B7CFF", icon: "school", popularity: 98 },
  { id: 2, slug: "clinic", name: "Clinic Flow", category: "Healthcare", description: "Appointments, patient records and reminders without the admin drag.", accent: "#A7E86C", icon: "clinic", popularity: 91 },
  { id: 3, slug: "shop", name: "Shop Launch", category: "Commerce", description: "A conversion-ready storefront with products and order tracking.", accent: "#F5B971", icon: "shop", popularity: 87 },
  { id: 4, slug: "portfolio", name: "Portfolio Signal", category: "Portfolio", description: "A sharp portfolio system for showing work and winning briefs.", accent: "#63D8FF", icon: "portfolio", popularity: 78 },
  { id: 5, slug: "booking", name: "Booking Desk", category: "Services", description: "Availability, payments and client bookings with less back-and-forth.", accent: "#F47EAB", icon: "booking", popularity: 82 },
  { id: 6, slug: "community", name: "Community Hub", category: "Community", description: "Member profiles, posts and moderation tools for your next network.", accent: "#C5A3FF", icon: "community", popularity: 66 },
];

const sampleBlueprint: Blueprint = {
  summary: "A focused command center for turning product ideas into build-ready applications.",
  pages: ["Landing", "Dashboard", "Settings"],
  tables: ["users", "projects", "activity"],
  roles: ["Owner", "Member"],
  checklist: ["Create the visual shell", "Connect the data model", "Run a preview build"],
};

function getView(path: string): View {
  if (path === "/templates") return "templates";
  if (path === "/preview") return "preview";
  if (path === "/domains") return "domains";
  if (path === "/publishing") return "publishing";
  if (path === "/mobile-builds") return "mobile";
  return "dashboard";
}

function StatusPill({ children, tone = "neutral" }: { children: React.ReactNode; tone?: "neutral" | "ready" | "warning" | "blocked" | "violet" }) {
  const classes = {
    neutral: "border-white/10 bg-white/[0.04] text-white/55",
    ready: "border-[#A7E86C]/20 bg-[#A7E86C]/10 text-[#BDF78A]",
    warning: "border-[#F5B971]/25 bg-[#F5B971]/10 text-[#F5C98B]",
    blocked: "border-[#FF7B91]/25 bg-[#FF7B91]/10 text-[#FF9CAD]",
    violet: "border-[#8B7CFF]/25 bg-[#8B7CFF]/10 text-[#B7B0FF]",
  }[tone];
  return <span className={`inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-medium ${classes}`}>{children}</span>;
}

function IconButton({ children, label, onClick }: { children: React.ReactNode; label: string; onClick?: () => void }) {
  return <button aria-label={label} onClick={onClick} className="grid h-9 w-9 place-items-center rounded-lg border border-white/10 bg-white/[0.03] text-white/50 transition hover:border-white/20 hover:bg-white/[0.07] hover:text-white">{children}</button>;
}

function SectionTitle({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail?: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex items-end justify-between gap-4"><div><p className="mb-2 font-mono text-[10px] uppercase tracking-[0.24em] text-[#8B7CFF]">{eyebrow}</p><h1 className="text-2xl font-semibold tracking-[-0.035em] text-white md:text-3xl">{title}</h1>{detail && <p className="mt-2 max-w-2xl text-sm leading-6 text-white/45">{detail}</p>}</div>{action}</div>;
}

function EmptyState({ title, detail, action }: { title: string; detail: string; action?: React.ReactNode }) {
  return <div className="flex min-h-[250px] flex-col items-center justify-center rounded-2xl border border-dashed border-white/10 bg-white/[0.02] p-8 text-center"><div className="mb-4 grid h-11 w-11 place-items-center rounded-xl border border-[#8B7CFF]/25 bg-[#8B7CFF]/10 text-[#B7B0FF]"><Sparkles className="h-5 w-5" /></div><h3 className="text-base font-medium text-white">{title}</h3><p className="mt-2 max-w-sm text-sm leading-6 text-white/40">{detail}</p>{action && <div className="mt-5">{action}</div>}</div>;
}

export default function Home() {
  const { user, loading, logout } = useAuth();
  const [location, setLocation] = useLocation();
  const view = getView(location);
  const [idea, setIdea] = useState("");
  const [projectName, setProjectName] = useState("Untitled build");
  const [chatMessages, setChatMessages] = useState<Message[]>([
    { role: "assistant", content: "Tell me what you want to build. I’ll ask the important product questions, shape the pages and data model, then build it with you." },
  ]);
  const [activeProjectId, setActiveProjectId] = useState<number | null>(null);
  const [blueprint, setBlueprint] = useState<Blueprint | null>(null);
  const [errorLog, setErrorLog] = useState("TypeError: Cannot read properties of undefined (reading 'map')\n  at ProjectList.tsx:42:18");
  const [diagnosis, setDiagnosis] = useState<Diagnosis | null>(null);
  const [domain, setDomain] = useState("");
  const [packageName, setPackageName] = useState("com.yourbrand.app");
  const [version, setVersion] = useState("1.0.0");
  const [buildKind, setBuildKind] = useState<"apk" | "aab">("apk");
  const [templateQuery, setTemplateQuery] = useState("");
  const [category, setCategory] = useState("All");
  const [mobileMenu, setMobileMenu] = useState(false);
  const [localEvent, setLocalEvent] = useState("Workspace ready");

  const projects = trpc.projects.list.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const templates = trpc.templates.list.useQuery();
  const generate = trpc.projects.generate.useMutation({ onSuccess: (data) => { setActiveProjectId(data.project?.id ?? null); setBlueprint(data.blueprint as Blueprint); setLocalEvent("Blueprint ready for review"); projects.refetch(); setLocation("/preview"); } });
  const chat = trpc.ai.chat.useMutation({ onSuccess: (data) => {
    setChatMessages(previous => [...previous, { role: "assistant", content: data.reply }]);
    if (data.projectName) setProjectName(data.projectName);
    if (data.shouldBuild && !generate.isPending) {
      setLocalEvent("Conversation complete — building your app");
      generate.mutate({ idea: data.buildBrief, name: data.projectName || projectName || "Untitled build" });
    }
  }, onError: () => setChatMessages(previous => [...previous, { role: "assistant", content: "I hit a temporary issue. Your conversation is safe—please send that message again." }]) });
  const generatedFiles = trpc.projects.files.useQuery({ id: activeProjectId ?? 0 }, { enabled: Boolean(activeProjectId), retry: false });
  const projectVersions = trpc.projects.versions.useQuery({ id: activeProjectId ?? 0 }, { enabled: Boolean(activeProjectId), retry: false });
  const generateFiles = trpc.projects.generateFiles.useMutation({ onSuccess: data => { setLocalEvent(`${data.files.length} source files generated`); generatedFiles.refetch(); } });
  const compilePreview = trpc.projects.compilePreview.useMutation({ onSuccess: data => { setLocalEvent(data.status === "ready" ? "Preview compile passed" : "Preview compile needs attention"); } });
  const diagnose = trpc.ai.diagnose.useMutation({ onSuccess: data => { setDiagnosis({ ...data.diagnosis, id: data.id }); setLocalEvent("AI repair proposal ready"); } });
  const applyRepair = trpc.ai.applyRepair.useMutation({ onSuccess: () => { setDiagnosis(null); setLocalEvent("AI repair applied and saved to history"); } });
  const connectDomain = trpc.deployment.connectDomain.useMutation({ onSuccess: () => setLocalEvent("Domain request saved") });
  const publish = trpc.deployment.publish.useMutation({ onSuccess: () => setLocalEvent("Publish request saved") });
  const mobileBuild = trpc.deployment.mobileBuild.useMutation({ onSuccess: () => setLocalEvent(`${buildKind.toUpperCase()} request saved`) });

  const catalog = (templates.data?.length ? templates.data : templateFallback) as typeof templateFallback;
  const filteredTemplates = useMemo(() => catalog.filter(template => (category === "All" || template.category === category) && `${template.name} ${template.description}`.toLowerCase().includes(templateQuery.toLowerCase())), [catalog, category, templateQuery]);
  const activeBlueprint = blueprint ?? sampleBlueprint;
  const categories = ["All", ...Array.from(new Set(catalog.map(template => template.category)))];
  const firstName = user?.name?.split(" ")[0] || "Builder";
  const activeProject = projects.data?.find(project => project.id === activeProjectId);
  const selectProject = (projectId: number) => {
    const project = projects.data?.find(item => item.id === projectId);
    if (!project) return;
    setActiveProjectId(projectId);
    if (project.blueprint) {
      try { setBlueprint(JSON.parse(project.blueprint) as Blueprint); } catch { setBlueprint(null); }
    }
    setLocalEvent(`${project.name} opened`);
    setLocation("/preview");
  };

  const beginGeneration = () => {
    if (!idea.trim()) return;
    if (!user) { startLogin(); return; }
    generate.mutate({ idea: idea.trim(), name: projectName.trim() || "Untitled build" });
  };

  const sendChatMessage = (content: string) => {
    if (!user) { startLogin(); return; }
    const nextMessages: Message[] = [...chatMessages, { role: "user", content }];
    setChatMessages(nextMessages);
    chat.mutate({ messages: nextMessages.map(message => ({ role: message.role === "user" ? "user" as const : "assistant" as const, content: message.content })), projectName });
  };

  const openTemplate = (slug: string) => {
    const template = catalog.find(item => item.slug === slug);
    if (!template) return;
    setIdea(`A ${template.category.toLowerCase()} app inspired by ${template.name}: ${template.description}`);
    setProjectName(template.name);
    setLocalEvent(`${template.name} loaded into the brief`);
    setLocation("/");
  };

  if (loading) return <div className="grid min-h-screen place-items-center bg-[#0B0C12] text-white/50"><Loader2 className="h-5 w-5 animate-spin" /></div>;
  if (!user) return <SignIn />;

  return <div className="min-h-screen bg-[#0B0C12] text-white selection:bg-[#8B7CFF]/30">
    <div className="pointer-events-none fixed inset-0 overflow-hidden"><div className="absolute -left-40 -top-40 h-[520px] w-[520px] rounded-full bg-[#7167FF]/[0.07] blur-[120px]" /><div className="absolute -bottom-48 right-0 h-[500px] w-[500px] rounded-full bg-[#A7E86C]/[0.035] blur-[130px]" /></div>
    <aside className={`fixed inset-y-0 left-0 z-50 flex w-[244px] flex-col border-r border-white/[0.07] bg-[#0B0C12]/95 px-4 py-5 backdrop-blur-xl transition-transform lg:translate-x-0 ${mobileMenu ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex items-center justify-between px-2"><button onClick={() => setLocation("/")} className="flex items-center gap-2.5"><span className="grid h-8 w-8 place-items-center rounded-[10px] bg-[#7167FF] shadow-[0_0_24px_rgba(113,103,255,0.35)]"><Sparkles className="h-4 w-4 text-white" /></span><span className="text-[15px] font-semibold tracking-[-0.03em]">forge<span className="text-[#A7E86C]">.</span></span></button><IconButton label="Close navigation" onClick={() => setMobileMenu(false)}><X className="h-4 w-4 lg:hidden" /></IconButton></div>
      <div className="mt-10 px-2"><p className="font-mono text-[9px] uppercase tracking-[0.22em] text-white/25">Workspace</p><nav className="mt-3 space-y-1">{navItems.map(item => { const active = location === item.path || (item.path === "/" && view === "dashboard"); return <button key={item.path} onClick={() => { setLocation(item.path); setMobileMenu(false); }} className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-[13px] transition ${active ? "border border-[#8B7CFF]/20 bg-[#8B7CFF]/10 text-white" : "text-white/43 hover:bg-white/[0.04] hover:text-white/80"}`}><item.icon className={`h-[15px] w-[15px] ${active ? "text-[#B7B0FF]" : "text-white/35"}`} />{item.label}{active && <ChevronRight className="ml-auto h-3.5 w-3.5 text-[#B7B0FF]" />}</button> })}</nav></div>
      <div className="mt-auto space-y-4"><div className="rounded-xl border border-[#A7E86C]/15 bg-[#A7E86C]/[0.045] p-3.5"><div className="flex items-center gap-2 text-[11px] font-medium text-[#BDF78A]"><CircleDot className="h-3.5 w-3.5" /> All systems operational</div><p className="mt-2 text-[10px] leading-4 text-white/35">AI generation and preview services are ready.</p></div><div className="flex items-center gap-2 border-t border-white/[0.07] px-2 pt-4"><div className="grid h-8 w-8 shrink-0 place-items-center rounded-full bg-gradient-to-br from-[#7167FF] to-[#A7E86C] text-[11px] font-semibold text-[#0B0C12]">{firstName.slice(0, 1).toUpperCase()}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium text-white/80">{user.name || "Builder"}</p><p className="truncate text-[10px] text-white/30">{user.email || "Manus account"}</p></div><button onClick={() => logout()} className="text-white/30 transition hover:text-white" aria-label="Sign out"><LogOut className="h-4 w-4" /></button></div></div>
    </aside>
    <main className="relative min-h-screen lg:pl-[244px]"><header className="sticky top-0 z-40 flex h-[68px] items-center justify-between border-b border-white/[0.07] bg-[#0B0C12]/75 px-5 backdrop-blur-xl md:px-9"><div className="flex items-center gap-3"><button onClick={() => setMobileMenu(true)} className="grid h-9 w-9 place-items-center rounded-lg border border-white/10 text-white/55 lg:hidden"><Menu className="h-4 w-4" /></button><div className="hidden items-center gap-2 text-[11px] text-white/30 md:flex"><span>Workspace</span><ChevronRight className="h-3 w-3" /><span className="text-white/65">{navItems.find(item => item.path === location)?.label || "Overview"}</span></div></div><div className="flex items-center gap-2"><div className="hidden items-center gap-2 rounded-lg border border-white/10 bg-white/[0.03] px-3 py-2 text-[11px] text-white/35 md:flex"><Search className="h-3.5 w-3.5" /> Quick search <kbd className="ml-3 rounded border border-white/10 px-1.5 py-0.5 font-mono text-[9px] text-white/30">⌘ K</kbd></div><IconButton label="Notifications"><Activity className="h-4 w-4" /></IconButton><IconButton label="Settings" onClick={() => setLocation("/domains")}><Settings2 className="h-4 w-4" /></IconButton></div></header>
      <div className="mx-auto max-w-[1440px] px-5 py-8 md:px-9 md:py-10">{view === "dashboard" && <DashboardView firstName={firstName} idea={idea} setIdea={setIdea} projectName={projectName} setProjectName={setProjectName} beginGeneration={beginGeneration} generate={generate} chatMessages={chatMessages} onSendChat={sendChatMessage} chatLoading={chat.isPending || generate.isPending} projects={projects.data ?? []} selectProject={selectProject} setLocation={setLocation} activeBlueprint={activeBlueprint} localEvent={localEvent} />}{view === "templates" && <TemplatesView categories={categories} category={category} setCategory={setCategory} templateQuery={templateQuery} setTemplateQuery={setTemplateQuery} filteredTemplates={filteredTemplates} openTemplate={openTemplate} />}{view === "preview" && <PreviewView activeProjectId={activeProjectId} activeProject={activeProject} blueprint={activeBlueprint} errorLog={errorLog} setErrorLog={setErrorLog} diagnosis={diagnosis} setDiagnosis={setDiagnosis} files={generatedFiles.data ?? []} versions={projectVersions.data ?? []} generateFiles={generateFiles} compilePreview={compilePreview} diagnose={diagnose} applyRepair={applyRepair} generate={generate} setLocation={setLocation} />}{view === "domains" && <DomainsView domain={domain} setDomain={setDomain} activeProjectId={activeProjectId} connectDomain={connectDomain} />}{view === "publishing" && <PublishingView activeProjectId={activeProjectId} publish={publish} localEvent={localEvent} />}{view === "mobile" && <MobileView activeProjectId={activeProjectId} packageName={packageName} setPackageName={setPackageName} version={version} setVersion={setVersion} buildKind={buildKind} setBuildKind={setBuildKind} mobileBuild={mobileBuild} />}</div>
    </main>
  </div>;
}

function SignIn() { return <div className="grid min-h-screen place-items-center bg-[#0B0C12] px-6 text-white"><div className="relative w-full max-w-md overflow-hidden rounded-3xl border border-white/10 bg-white/[0.035] p-8 text-center shadow-2xl"><div className="absolute -right-20 -top-24 h-48 w-48 rounded-full bg-[#7167FF]/20 blur-3xl" /><div className="relative"><div className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#7167FF] shadow-[0_0_35px_rgba(113,103,255,0.4)]"><Sparkles className="h-6 w-6" /></div><p className="mt-6 font-mono text-[10px] uppercase tracking-[0.24em] text-[#A7E86C]">AI app builder</p><h1 className="mt-3 text-3xl font-semibold tracking-[-0.05em]">Your idea, in build mode.</h1><p className="mx-auto mt-3 max-w-sm text-sm leading-6 text-white/45">Describe a product and forge will map the pages, data and next deployment step.</p><button onClick={() => startLogin()} className="mt-7 flex w-full items-center justify-center gap-2 rounded-xl bg-[#7167FF] px-4 py-3 text-sm font-semibold text-white transition hover:bg-[#8279ff]"><LockKeyhole className="h-4 w-4" /> Continue with Manus</button><p className="mt-4 text-[11px] text-white/25">Protected workspace · OAuth secured</p></div></div></div>; }

function DashboardView({ firstName, idea, setIdea, projectName, setProjectName, beginGeneration, generate, chatMessages, onSendChat, chatLoading, projects, selectProject, setLocation, activeBlueprint, localEvent }: { firstName: string; idea: string; setIdea: (value: string) => void; projectName: string; setProjectName: (value: string) => void; beginGeneration: () => void; generate: { isPending: boolean; error: unknown }; chatMessages: Message[]; onSendChat: (content: string) => void; chatLoading: boolean; projects: Array<{ id: number; name: string; status: string; description: string | null; updatedAt: Date }>; selectProject: (projectId: number) => void; setLocation: (path: string) => void; activeBlueprint: Blueprint; localEvent: string }) {
  return <><SectionTitle eyebrow="Command center / 01" title={`Good to see you, ${firstName}.`} detail="Turn a product brief into a clear, build-ready system—then keep every change visible." action={<button onClick={() => setLocation("/templates")} className="hidden items-center gap-2 rounded-lg border border-white/10 bg-white/[0.03] px-3.5 py-2.5 text-xs text-white/65 transition hover:border-white/20 hover:text-white md:flex"><Boxes className="h-3.5 w-3.5" /> Browse templates</button>} />
    <div className="grid gap-5 xl:grid-cols-[minmax(0,1.45fr)_minmax(310px,0.7fr)]"><div className="relative overflow-hidden rounded-2xl border border-[#8B7CFF]/25 bg-gradient-to-br from-[#17162C] via-[#141526] to-[#11131B] p-6 shadow-[0_18px_60px_rgba(28,23,75,0.2)] md:p-8"><div className="absolute right-0 top-0 h-52 w-52 rounded-full bg-[#7167FF]/10 blur-3xl" /><div className="relative"><div className="flex items-center justify-between"><div className="flex items-center gap-2 text-xs font-medium text-[#C3BDFF]"><span className="grid h-6 w-6 place-items-center rounded-md bg-[#7167FF]/20"><Sparkles className="h-3.5 w-3.5" /></span> AI App Generation</div><StatusPill tone="violet"><Zap className="h-3 w-3" /> Ready to forge</StatusPill></div><h2 className="mt-7 max-w-xl text-2xl font-semibold tracking-[-0.04em] text-white md:text-3xl">Describe the product.<br /><span className="text-white/45">We’ll map the build.</span></h2><p className="mt-3 max-w-lg text-sm leading-6 text-white/45">Start with a sentence, a messy thought or a customer problem. Forge turns it into pages, data and roles you can review.</p><div className="mt-7 rounded-xl border border-white/10 bg-[#0B0C12]/55 p-3"><div className="mb-3 flex flex-col gap-2 border-b border-white/[0.07] px-2 pb-3 sm:flex-row sm:items-center"><div className="flex-1"><p className="text-[10px] uppercase tracking-[0.18em] text-white/30">Build conversation</p><p className="mt-1 text-[11px] text-white/35">Discuss the product. When the plan is clear, Forge starts building automatically.</p></div><input value={projectName} onChange={event => setProjectName(event.target.value)} className="h-9 rounded-lg border border-white/10 bg-white/[0.04] px-3 text-xs text-white/70 outline-none placeholder:text-white/25 focus:border-[#8B7CFF]/50" placeholder="Project name" /></div><AIChatBox messages={chatMessages} onSendMessage={onSendChat} isLoading={chatLoading} height={360} className="border-0 bg-transparent shadow-none" placeholder="Tell the AI what to build, change, or decide next..." emptyStateMessage="Your AI product partner is ready" suggestedPrompts={["I want to build a clinic booking app", "Ask me the important questions first", "Build a simple shop with login and payments"]} /></div>{Boolean(generate.error) && <p className="mt-3 flex items-center gap-2 text-xs text-[#FF9CAD]"><AlertTriangle className="h-3.5 w-3.5" /> Could not generate yet. Your brief is safe—retry when ready.</p>}</div></div><div className="rounded-2xl border border-white/[0.08] bg-white/[0.025] p-6"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[0.22em] text-white/30">Build pulse</p><h3 className="mt-2 text-lg font-medium text-white">System telemetry</h3></div><MoreHorizontal className="h-4 w-4 text-white/30" /></div><div className="mt-7 space-y-5"><MetricRow icon={<Cpu />} label="AI orchestration" value="Operational" tone="ready" /><MetricRow icon={<Cloud />} label="Preview runtime" value="Listening" tone="ready" /><MetricRow icon={<Hammer />} label="Deploy pipeline" value="Not connected" tone="warning" /></div><div className="mt-7 border-t border-white/[0.07] pt-4"><div className="flex items-center justify-between text-xs"><span className="text-white/35">Latest event</span><span className="font-mono text-[10px] text-white/25">just now</span></div><p className="mt-2 text-sm text-white/65">{localEvent}</p></div></div></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[minmax(0,1fr)_minmax(310px,0.58fr)]"><div className="rounded-2xl border border-white/[0.08] bg-white/[0.025] p-6"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[0.22em] text-white/30">Recent projects</p><h3 className="mt-2 text-lg font-medium text-white">Your build queue</h3></div><button onClick={() => setLocation("/preview")} className="text-xs text-[#B7B0FF] transition hover:text-white">Open workspace <ArrowRight className="ml-1 inline h-3.5 w-3.5" /></button></div>{projects.length ? <div className="mt-5 divide-y divide-white/[0.07]">{projects.slice(0, 4).map(project => <div key={project.id} onClick={() => selectProject(project.id)} className="flex cursor-pointer items-center gap-4 py-4 transition hover:bg-white/[0.025]"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-lg border border-white/10 bg-white/[0.04] text-white/40"><FileCode2 className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium text-white/80">{project.name}</p><p className="mt-1 truncate text-xs text-white/30">{project.description || "Blueprint in progress"}</p></div><StatusPill tone={project.status === "ready" ? "ready" : "violet"}>{project.status}</StatusPill><ChevronRight className="hidden h-4 w-4 text-white/20 sm:block" /></div>)}</div> : <div className="mt-5"><EmptyState title="Your first build is one brief away" detail="Generate a blueprint and it will appear here with its next action." action={<button onClick={() => document.querySelector("textarea")?.focus()} className="rounded-lg border border-white/10 px-3 py-2 text-xs text-white/65 hover:bg-white/[0.06]">Write a brief</button>} /></div>}</div><div className="rounded-2xl border border-white/[0.08] bg-white/[0.025] p-6"><p className="font-mono text-[10px] uppercase tracking-[0.22em] text-white/30">Blueprint snapshot</p><h3 className="mt-2 text-lg font-medium text-white">What your app gets</h3><div className="mt-6 space-y-4"><SnapshotRow icon={<LayoutDashboard />} label="Pages mapped" value={`${activeBlueprint.pages.length} screens`} /><SnapshotRow icon={<Boxes />} label="Data model" value={`${activeBlueprint.tables.length} tables`} /><SnapshotRow icon={<LockKeyhole />} label="Access roles" value={`${activeBlueprint.roles.length} roles`} /></div><button onClick={() => setLocation("/preview")} className="mt-7 flex w-full items-center justify-between rounded-lg border border-white/10 bg-white/[0.03] px-3.5 py-3 text-xs font-medium text-white/65 transition hover:border-[#8B7CFF]/40 hover:text-white">Review generated plan <ArrowRight className="h-3.5 w-3.5" /></button></div></div>
  </>;
}

function MetricRow({ icon, label, value, tone }: { icon: React.ReactNode; label: string; value: string; tone: "ready" | "warning" }) { return <div className="flex items-center gap-3"><span className="grid h-8 w-8 place-items-center rounded-lg border border-white/10 bg-white/[0.04] text-white/40">{icon && <span className="h-4 w-4">{icon}</span>}</span><span className="flex-1 text-xs text-white/55">{label}</span><StatusPill tone={tone}><span className={`h-1.5 w-1.5 rounded-full ${tone === "ready" ? "bg-[#A7E86C]" : "bg-[#F5B971]"}`} />{value}</StatusPill></div>; }
function SnapshotRow({ icon, label, value }: { icon: React.ReactNode; label: string; value: string }) { return <div className="flex items-center gap-3"><span className="text-[#8B7CFF]">{icon}</span><span className="flex-1 text-xs text-white/45">{label}</span><span className="font-mono text-[11px] text-white/75">{value}</span></div>; }

function TemplatesView({ categories, category, setCategory, templateQuery, setTemplateQuery, filteredTemplates, openTemplate }: { categories: string[]; category: string; setCategory: (value: string) => void; templateQuery: string; setTemplateQuery: (value: string) => void; filteredTemplates: typeof templateFallback; openTemplate: (slug: string) => void }) { return <><SectionTitle eyebrow="Marketplace / 02" title="Start from a strong first draft." detail="Ready-made systems for the moments founders rebuild most often. Pick one, then make it yours." action={<StatusPill tone="ready"><CheckCircle2 className="h-3.5 w-3.5" /> 6 templates online</StatusPill>} /><div className="mb-6 flex flex-col gap-3 md:flex-row md:items-center"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/30" /><input value={templateQuery} onChange={event => setTemplateQuery(event.target.value)} placeholder="Search templates..." className="h-11 w-full rounded-xl border border-white/10 bg-white/[0.035] pl-10 pr-4 text-sm text-white outline-none placeholder:text-white/25 focus:border-[#8B7CFF]/50" /></div><div className="flex gap-1.5 overflow-auto pb-1">{categories.map(item => <button key={item} onClick={() => setCategory(item)} className={`whitespace-nowrap rounded-lg border px-3 py-2 text-xs transition ${category === item ? "border-[#8B7CFF]/35 bg-[#8B7CFF]/10 text-[#C3BDFF]" : "border-white/10 text-white/38 hover:text-white/70"}`}>{item}</button>)}</div></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filteredTemplates.map(template => <div key={template.slug} className="group relative overflow-hidden rounded-2xl border border-white/[0.08] bg-white/[0.025] p-5 transition duration-300 hover:-translate-y-0.5 hover:border-white/20 hover:bg-white/[0.04]"><div className="absolute inset-x-0 top-0 h-0.5 opacity-80" style={{ background: template.accent }} /><div className="flex items-start justify-between"><div className="grid h-11 w-11 place-items-center rounded-xl border border-white/10 bg-white/[0.045]" style={{ color: template.accent }}><TemplateIcon icon={template.icon} /></div><span className="font-mono text-[10px] text-white/25">{String(template.popularity).padStart(2, "0")} uses</span></div><p className="mt-6 font-mono text-[10px] uppercase tracking-[0.18em] text-white/30">{template.category}</p><h3 className="mt-2 text-lg font-medium text-white">{template.name}</h3><p className="mt-2 min-h-[48px] text-sm leading-6 text-white/40">{template.description}</p><div className="mt-6 flex items-center gap-2"><button onClick={() => openTemplate(template.slug)} className="flex flex-1 items-center justify-center gap-2 rounded-lg bg-white px-3 py-2.5 text-xs font-semibold text-[#101117] transition hover:bg-[#DAD8FF]"><Plus className="h-3.5 w-3.5" /> Use template</button><IconButton label={`Preview ${template.name}`} onClick={() => openTemplate(template.slug)}><ExternalLink className="h-3.5 w-3.5" /></IconButton></div></div>)}</div>{filteredTemplates.length === 0 && <EmptyState title="No templates match that search" detail="Try a wider category or search for another product shape." />}</>; }
function TemplateIcon({ icon }: { icon: string }) { const Icon = icon === "school" ? Code2 : icon === "clinic" ? LifeBuoy : icon === "shop" ? Package : icon === "portfolio" ? Terminal : icon === "booking" ? Activity : Boxes; return <Icon className="h-5 w-5" />; }

function PreviewView({ activeProjectId, activeProject, blueprint, files, versions, generateFiles, compilePreview, errorLog, setErrorLog, diagnosis, setDiagnosis, diagnose, applyRepair, generate, setLocation }: { activeProjectId: number | null; activeProject?: { name: string } | undefined; blueprint: Blueprint; files: Array<{ id: number; path: string; kind: string; content: string }>; versions: Array<{ id: number; label: string; summary: string; createdAt: Date }>; generateFiles: { isPending: boolean; mutate: (input: { projectId: number }) => void; error: unknown }; compilePreview: { isPending: boolean; mutate: (input: { projectId: number }) => void; error: unknown }; errorLog: string; setErrorLog: (value: string) => void; diagnosis: Diagnosis | null; setDiagnosis: (value: null) => void; diagnose: { isPending: boolean; mutate: (input: { projectId: number; errorLog: string }) => void; error: unknown }; applyRepair: { isPending: boolean; mutate: (input: { projectId: number; bugId: number }) => void; error: unknown }; generate: { isPending: boolean }; setLocation: (path: string) => void }) { return <><SectionTitle eyebrow="Workspace / 03" title="Preview, inspect, repair." detail="The build surface is intentionally visible: see the page map, inspect errors and review every proposed repair." action={<div className="flex items-center gap-2"><StatusPill tone="ready"><span className="h-1.5 w-1.5 rounded-full bg-[#A7E86C]" /> Preview live</StatusPill><button onClick={() => setLocation("/publishing")} className="hidden items-center gap-2 rounded-lg bg-[#7167FF] px-3.5 py-2.5 text-xs font-semibold md:flex">Publish <ArrowRight className="h-3.5 w-3.5" /></button></div>} /><div className="grid gap-5 xl:grid-cols-[minmax(0,1.25fr)_minmax(320px,0.75fr)]"><div className="overflow-hidden rounded-2xl border border-white/[0.09] bg-[#12141C]"><div className="flex items-center gap-2 border-b border-white/[0.08] bg-white/[0.025] px-4 py-3"><div className="flex gap-1.5"><span className="h-2.5 w-2.5 rounded-full bg-[#FF7B91]/80" /><span className="h-2.5 w-2.5 rounded-full bg-[#F5B971]/80" /><span className="h-2.5 w-2.5 rounded-full bg-[#A7E86C]/80" /></div><div className="mx-auto flex items-center gap-2 rounded-md border border-white/10 bg-black/15 px-3 py-1 text-[10px] text-white/25"><LockKeyhole className="h-3 w-3" /> preview.forge.app/{activeProject?.name?.toLowerCase().replace(/\s+/g, "-") || "your-app"}</div><MoreHorizontal className="h-4 w-4 text-white/25" /></div><div className="grid min-h-[480px] grid-cols-[145px_1fr] bg-[#0F1118]"><div className="border-r border-white/[0.07] bg-white/[0.015] p-4"><div className="mb-5 flex items-center gap-2"><span className="grid h-6 w-6 place-items-center rounded-md bg-[#7167FF]"><Sparkles className="h-3.5 w-3.5" /></span><span className="text-[11px] font-semibold text-white/75">{activeProject?.name || "Your app"}</span></div><div className="space-y-1">{blueprint.pages.map((page, index) => <div key={page} className={`rounded-md px-2.5 py-2 text-[11px] ${index === 0 ? "bg-[#8B7CFF]/12 text-[#C3BDFF]" : "text-white/35"}`}>{page}</div>)}</div><div className="mt-8 border-t border-white/[0.07] pt-4"><p className="font-mono text-[9px] uppercase tracking-widest text-white/20">Data</p>{blueprint.tables.map(table => <p key={table} className="mt-3 flex items-center gap-2 text-[10px] text-white/35"><Boxes className="h-3 w-3" />{table}</p>)}</div></div><div className="relative p-6 md:p-10"><div className="mx-auto max-w-[470px]"><div className="flex items-center justify-between"><div><p className="font-mono text-[9px] uppercase tracking-[0.18em] text-[#8B7CFF]">Generated interface</p><h3 className="mt-2 text-xl font-semibold tracking-[-0.03em]">{blueprint.pages[0] || "Landing"}</h3></div><span className="rounded-md border border-[#A7E86C]/20 bg-[#A7E86C]/10 px-2 py-1 font-mono text-[9px] text-[#BDF78A]">v0.1.0</span></div><div className="mt-8 h-24 rounded-xl border border-white/[0.08] bg-gradient-to-r from-[#7167FF]/25 via-[#7167FF]/5 to-transparent p-5"><div className="h-2 w-32 rounded-full bg-white/70" /><div className="mt-3 h-2 w-56 rounded-full bg-white/15" /><div className="mt-2 h-2 w-40 rounded-full bg-white/10" /></div><div className="mt-5 grid grid-cols-3 gap-3">{[1, 2, 3].map(item => <div key={item} className="h-20 rounded-xl border border-white/[0.07] bg-white/[0.025] p-3"><div className="h-5 w-5 rounded-md bg-[#A7E86C]/15" /><div className="mt-3 h-1.5 w-12 rounded-full bg-white/20" /><div className="mt-2 h-1.5 w-8 rounded-full bg-white/10" /></div>)}</div><div className="mt-6 flex items-center gap-2 rounded-lg border border-dashed border-white/10 px-3 py-3 text-xs text-white/30"><Sparkles className="h-3.5 w-3.5 text-[#8B7CFF]" /> AI generated structure is ready to customize</div></div></div></div></div><div className="space-y-5"><div className="rounded-2xl border border-white/[0.09] bg-white/[0.025] p-5"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[0.2em] text-white/30">Build map</p><h3 className="mt-2 text-lg font-medium">Blueprint details</h3></div><FileCode2 className="h-4 w-4 text-[#8B7CFF]" /></div><p className="mt-4 text-sm leading-6 text-white/45">{blueprint.summary}</p><div className="mt-5 space-y-3">{[["Pages", blueprint.pages.join(" · ")], ["Data", blueprint.tables.join(" · ")], ["Roles", blueprint.roles.join(" · ")]].map(([label, value]) => <div key={label} className="border-t border-white/[0.07] pt-3"><p className="font-mono text-[9px] uppercase tracking-wider text-white/25">{label}</p><p className="mt-1 text-xs text-white/70">{value}</p></div>)}</div></div><div className="rounded-2xl border border-white/[0.09] bg-white/[0.025] p-5"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[0.2em] text-white/30">Source tree</p><h3 className="mt-2 text-lg font-medium">Generated files</h3><p className="mt-1 text-[10px] text-white/30">{versions.length} saved version{versions.length === 1 ? "" : "s"}</p></div><Code2 className="h-4 w-4 text-[#A7E86C]" /></div><div className="mt-4 space-y-2">{files.slice(0, 6).map(file => <div key={file.id} className="flex items-center gap-2 rounded-md border border-white/[0.06] bg-black/10 px-2.5 py-2"><FileCode2 className="h-3.5 w-3.5 text-white/30" /><span className="flex-1 truncate font-mono text-[10px] text-white/60">{file.path}</span><span className="text-[9px] uppercase text-white/25">{file.kind}</span></div>)}{!files.length && <p className="text-xs leading-5 text-white/35">No source files yet. Generate a real file tree from this blueprint.</p>}</div><button disabled={!activeProjectId || generateFiles.isPending} onClick={() => activeProjectId && generateFiles.mutate({ projectId: activeProjectId })} className="mt-4 flex w-full items-center justify-center gap-2 rounded-lg border border-[#A7E86C]/25 bg-[#A7E86C]/10 px-3 py-2.5 text-xs font-semibold text-[#BDF78A] disabled:opacity-40">{generateFiles.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Code2 className="h-3.5 w-3.5" />}{files.length ? "Regenerate source files" : "Generate source files"}</button><button disabled={!activeProjectId || compilePreview.isPending || !files.length} onClick={() => activeProjectId && compilePreview.mutate({ projectId: activeProjectId })} className="mt-2 flex w-full items-center justify-center gap-2 rounded-lg border border-[#8B7CFF]/25 bg-[#8B7CFF]/10 px-3 py-2.5 text-xs font-semibold text-[#C3BDFF] disabled:opacity-40">{compilePreview.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Play className="h-3.5 w-3.5" />}Compile generated preview</button><SourceEditor files={files} activeProjectId={activeProjectId} />{Boolean(generateFiles.error) && <p className="mt-2 text-[10px] text-[#FF9CAD]">Generation failed—retry without losing your blueprint.</p>}</div><div className="rounded-2xl border border-[#F5B971]/20 bg-[#F5B971]/[0.04] p-5"><div className="flex items-start justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[0.2em] text-[#F5C98B]/60">Bug Fix AI</p><h3 className="mt-2 text-lg font-medium">Inspect an error</h3></div><Wand2 className="h-4 w-4 text-[#F5B971]" /></div><textarea value={errorLog} onChange={event => setErrorLog(event.target.value)} className="mt-4 min-h-[102px] w-full resize-none rounded-lg border border-white/10 bg-black/20 p-3 font-mono text-[10px] leading-5 text-[#F5C98B]/80 outline-none" />{diagnosis ? <div className="mt-4 rounded-lg border border-[#A7E86C]/20 bg-[#A7E86C]/[0.06] p-3"><div className="flex items-center justify-between"><StatusPill tone="ready"><CheckCircle2 className="h-3 w-3" /> Proposal ready</StatusPill><button onClick={() => setDiagnosis(null)} className="text-white/30 hover:text-white"><X className="h-3.5 w-3.5" /></button></div><p className="mt-3 text-xs leading-5 text-white/70">{diagnosis.summary}</p><p className="mt-2 text-[10px] text-white/35">{diagnosis.affectedArea} · {Math.round(diagnosis.confidence * 100)}% confidence</p><div className="mt-3 space-y-1.5">{diagnosis.steps.map(step => <p key={step} className="flex gap-2 text-[10px] text-white/50"><Check className="h-3 w-3 shrink-0 text-[#A7E86C]" />{step}</p>)}</div>{Boolean(diagnosis.patches?.length) && <div className="mt-3 rounded-md border border-white/[0.08] bg-black/15 p-2.5"><p className="font-mono text-[9px] uppercase tracking-wider text-white/30">Reviewable patch</p>{diagnosis.patches?.map(patch => <p key={patch.path} className="mt-1 text-[10px] text-white/55"><span className="font-mono text-[#C3BDFF]">{patch.path}</span> · {patch.reason}</p>)}</div>}<button disabled={applyRepair.isPending} onClick={() => activeProjectId && applyRepair.mutate({ projectId: activeProjectId, bugId: diagnosis.id })} className="mt-4 flex w-full items-center justify-center gap-2 rounded-lg bg-[#A7E86C] px-3 py-2 text-xs font-semibold text-[#0B0C12] disabled:opacity-50">{applyRepair.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Wand2 className="h-3.5 w-3.5" />} {applyRepair.isPending ? "Applying repair..." : "Apply repair"}</button></div> : <button disabled={!activeProjectId || diagnose.isPending || generate.isPending} onClick={() => activeProjectId && diagnose.mutate({ projectId: activeProjectId, errorLog })} className="mt-3 flex w-full items-center justify-center gap-2 rounded-lg border border-[#F5B971]/25 bg-[#F5B971]/10 px-3 py-2.5 text-xs font-semibold text-[#F5C98B] transition hover:bg-[#F5B971]/15 disabled:cursor-not-allowed disabled:opacity-40">{diagnose.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Send className="h-3.5 w-3.5" />}{activeProjectId ? "Diagnose with AI" : "Generate a project first"}</button>}{Boolean(diagnose.error) && <p className="mt-2 text-[10px] text-[#FF9CAD]">Diagnosis failed—your error log is still here to retry.</p>}</div></div></div></> }

function SourceEditor({ files, activeProjectId }: { files: Array<{ id: number; path: string; kind: string; content: string }>; activeProjectId: number | null }) {
  const [selectedId, setSelectedId] = useState<number | null>(files[0]?.id ?? null);
  const selected = files.find(file => file.id === selectedId) ?? files[0];
  const [draft, setDraft] = useState(selected?.content ?? "");
  const save = trpc.projects.saveFile.useMutation();
  useEffect(() => { if (selected) setDraft(selected.content); }, [selected?.id, selected?.content]);
  if (!files.length) return null;
  return <div className="mt-4 overflow-hidden rounded-lg border border-white/[0.08] bg-[#0B0C12]/60"><div className="flex gap-1 overflow-auto border-b border-white/[0.08] p-1">{files.slice(0, 6).map(file => <button key={file.id} onClick={() => setSelectedId(file.id)} className={`whitespace-nowrap rounded-md px-2 py-1.5 font-mono text-[9px] ${file.id === selected?.id ? "bg-[#8B7CFF]/15 text-[#C3BDFF]" : "text-white/35 hover:text-white/70"}`}>{file.path.split("/").pop()}</button>)}</div><textarea value={draft} onChange={event => setDraft(event.target.value)} className="min-h-[150px] w-full resize-y bg-transparent p-3 font-mono text-[10px] leading-5 text-white/65 outline-none" spellCheck={false} /><div className="flex items-center justify-between border-t border-white/[0.08] px-3 py-2"><span className="truncate font-mono text-[9px] text-white/25">{selected?.path}</span><button disabled={!activeProjectId || !selected || save.isPending} onClick={() => activeProjectId && selected && save.mutate({ projectId: activeProjectId, path: selected.path, kind: selected.kind, content: draft })} className="rounded-md bg-[#7167FF] px-2.5 py-1.5 text-[10px] font-semibold text-white disabled:opacity-40">{save.isPending ? "Saving..." : "Save file"}</button></div>{save.isSuccess && <p className="px-3 pb-2 text-[9px] text-[#BDF78A]">Saved as a new project version.</p>}</div>;
}

function DomainsView({ domain, setDomain, activeProjectId, connectDomain }: { domain: string; setDomain: (value: string) => void; activeProjectId: number | null; connectDomain: { isPending: boolean; mutate: (input: { projectId: number; hostname: string }) => void } }) { return <><SectionTitle eyebrow="Infrastructure / 04" title="Bring your own domain." detail="Connect the place your customers already know. We’ll keep DNS, SSL and verification state in one place." action={<StatusPill tone="warning"><CircleDot className="h-3.5 w-3.5" /> Provider not connected</StatusPill>} /><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_minmax(310px,0.55fr)]"><div className="rounded-2xl border border-white/[0.09] bg-white/[0.025] p-6 md:p-8"><div className="flex h-12 w-12 items-center justify-center rounded-xl border border-[#63D8FF]/25 bg-[#63D8FF]/10 text-[#63D8FF]"><Globe2 className="h-5 w-5" /></div><h2 className="mt-6 text-xl font-semibold">Connect a custom domain</h2><p className="mt-2 max-w-lg text-sm leading-6 text-white/40">Use your own domain for a polished launch. The request is saved now; a DNS provider connection will run the verification.</p><label className="mt-7 block font-mono text-[10px] uppercase tracking-wider text-white/30">Hostname</label><div className="mt-2 flex flex-col gap-2 sm:flex-row"><input value={domain} onChange={event => setDomain(event.target.value)} placeholder="app.yourbrand.com" className="h-11 flex-1 rounded-lg border border-white/10 bg-black/20 px-3 text-sm text-white outline-none placeholder:text-white/25 focus:border-[#63D8FF]/50" /><button disabled={!activeProjectId || !domain || connectDomain.isPending} onClick={() => activeProjectId && connectDomain.mutate({ projectId: activeProjectId, hostname: domain })} className="flex items-center justify-center gap-2 rounded-lg bg-[#63D8FF] px-4 py-2 text-xs font-semibold text-[#0B0C12] disabled:opacity-40">{connectDomain.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Plus className="h-3.5 w-3.5" />} Add domain</button></div><p className="mt-3 text-[11px] text-white/25">{activeProjectId ? "This project is selected." : "Generate or select a project before adding a domain."}</p></div><div className="rounded-2xl border border-white/[0.09] bg-white/[0.025] p-6"><p className="font-mono text-[10px] uppercase tracking-[0.2em] text-white/30">Connection checklist</p><div className="mt-6 space-y-4"><ChecklistRow label="Domain request" state="ready" /><ChecklistRow label="DNS record" state="pending" /><ChecklistRow label="SSL certificate" state="pending" /></div><div className="mt-6 rounded-lg border border-[#F5B971]/15 bg-[#F5B971]/[0.05] p-3 text-xs leading-5 text-[#F5C98B]/75"><AlertTriangle className="mr-2 inline h-3.5 w-3.5" /> External DNS access is needed to complete verification.</div></div></div></>; }
function ChecklistRow({ label, state }: { label: string; state: "ready" | "pending" }) { return <div className="flex items-center gap-3"><span className={`grid h-7 w-7 place-items-center rounded-lg ${state === "ready" ? "bg-[#A7E86C]/10 text-[#A7E86C]" : "bg-white/[0.05] text-white/25"}`}>{state === "ready" ? <Check className="h-3.5 w-3.5" /> : <CircleDot className="h-3.5 w-3.5" />}</span><span className="flex-1 text-xs text-white/55">{label}</span><span className="font-mono text-[9px] uppercase text-white/25">{state}</span></div>; }

function PublishingView({ activeProjectId, publish, localEvent }: { activeProjectId: number | null; publish: { isPending: boolean; mutate: (input: { projectId: number }) => void }; localEvent: string }) { return <><SectionTitle eyebrow="Release lane / 05" title="Ship when the signal is green." detail="One click should be all it takes. Until a provider is connected, forge will keep the request visible and safe." action={<StatusPill tone="warning"><CircleDot className="h-3.5 w-3.5" /> Integration needed</StatusPill>} /><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_minmax(310px,0.6fr)]"><div className="rounded-2xl border border-white/[0.09] bg-white/[0.025] p-6 md:p-8"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[0.2em] text-white/30">Web publish</p><h2 className="mt-2 text-2xl font-semibold">Release candidate</h2></div><div className="grid h-12 w-12 place-items-center rounded-xl border border-[#8B7CFF]/25 bg-[#8B7CFF]/10 text-[#B7B0FF]"><Rocket className="h-5 w-5" /></div></div><div className="mt-8 space-y-3"><ReleaseStep label="Blueprint reviewed" done /><ReleaseStep label="Preview build" done /><ReleaseStep label="Production deploy" /></div><button disabled={!activeProjectId || publish.isPending} onClick={() => activeProjectId && publish.mutate({ projectId: activeProjectId })} className="mt-8 flex items-center justify-center gap-2 rounded-lg bg-[#7167FF] px-4 py-3 text-xs font-semibold text-white disabled:opacity-40">{publish.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Rocket className="h-3.5 w-3.5" />}{activeProjectId ? "Publish web app" : "Select a project to publish"}</button></div><div className="rounded-2xl border border-white/[0.09] bg-white/[0.025] p-6"><p className="font-mono text-[10px] uppercase tracking-[0.2em] text-white/30">Latest release event</p><div className="mt-6 flex gap-3"><span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-[#F5B971] shadow-[0_0_12px_rgba(245,185,113,0.7)]" /><div><p className="text-sm text-white/75">{localEvent}</p><p className="mt-1 text-xs leading-5 text-white/35">No public URL is shown until a real deployment confirms the release.</p></div></div><div className="mt-8 rounded-lg border border-white/[0.07] bg-black/15 p-3 font-mono text-[10px] leading-5 text-white/30">$ forge publish --project current<br /><span className="text-[#F5C98B]">→ waiting for deploy provider</span></div></div></div></>; }
function ReleaseStep({ label, done = false }: { label: string; done?: boolean }) { return <div className="flex items-center gap-3 rounded-lg border border-white/[0.07] bg-black/10 px-3 py-3"><span className={`grid h-7 w-7 place-items-center rounded-lg ${done ? "bg-[#A7E86C]/10 text-[#A7E86C]" : "bg-[#F5B971]/10 text-[#F5C98B]"}`}>{done ? <Check className="h-3.5 w-3.5" /> : <CircleDot className="h-3.5 w-3.5" />}</span><span className="flex-1 text-xs text-white/65">{label}</span><span className={`font-mono text-[9px] uppercase ${done ? "text-[#A7E86C]" : "text-[#F5C98B]"}`}>{done ? "ready" : "blocked"}</span></div>; }

function MobileView({ activeProjectId, packageName, setPackageName, version, setVersion, buildKind, setBuildKind, mobileBuild }: { activeProjectId: number | null; packageName: string; setPackageName: (value: string) => void; version: string; setVersion: (value: string) => void; buildKind: "apk" | "aab"; setBuildKind: (value: "apk" | "aab") => void; mobileBuild: { isPending: boolean; mutate: (input: { projectId: number; kind: "apk" | "aab"; packageName: string; version: string }) => void } }) { return <><SectionTitle eyebrow="Mobile lane / 06" title="Turn web into an Android build." detail="Choose the artifact shape, set your package identity and keep signing/build status explicit." action={<StatusPill tone="violet"><Smartphone className="h-3.5 w-3.5" /> Android pipeline</StatusPill>} /><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_minmax(310px,0.58fr)]"><div className="rounded-2xl border border-white/[0.09] bg-white/[0.025] p-6 md:p-8"><div className="flex h-12 w-12 items-center justify-center rounded-xl border border-[#A7E86C]/25 bg-[#A7E86C]/10 text-[#A7E86C]"><Smartphone className="h-5 w-5" /></div><h2 className="mt-6 text-xl font-semibold">Build configuration</h2><div className="mt-6 grid gap-4 md:grid-cols-2"><label className="block text-xs text-white/40 md:col-span-2">Package name<input value={packageName} onChange={event => setPackageName(event.target.value)} className="mt-2 h-11 w-full rounded-lg border border-white/10 bg-black/20 px-3 font-mono text-xs text-white outline-none focus:border-[#8B7CFF]/50" /></label><label className="block text-xs text-white/40">Version<input value={version} onChange={event => setVersion(event.target.value)} className="mt-2 h-11 w-full rounded-lg border border-white/10 bg-black/20 px-3 font-mono text-xs text-white outline-none focus:border-[#8B7CFF]/50" /></label><div><p className="text-xs text-white/40">Artifact</p><div className="mt-2 flex gap-2">{(["apk", "aab"] as const).map(kind => <button key={kind} onClick={() => setBuildKind(kind)} className={`flex-1 rounded-lg border px-3 py-3 font-mono text-xs uppercase transition ${buildKind === kind ? "border-[#A7E86C]/35 bg-[#A7E86C]/10 text-[#BDF78A]" : "border-white/10 text-white/35 hover:text-white/70"}`}>{kind}</button>)}</div></div></div><button disabled={!activeProjectId || mobileBuild.isPending} onClick={() => activeProjectId && mobileBuild.mutate({ projectId: activeProjectId, kind: buildKind, packageName, version })} className="mt-7 flex items-center justify-center gap-2 rounded-lg bg-[#A7E86C] px-4 py-3 text-xs font-semibold text-[#0B0C12] disabled:opacity-40">{mobileBuild.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Hammer className="h-3.5 w-3.5" />}{activeProjectId ? `Build ${buildKind.toUpperCase()}` : "Select a project first"}</button></div><div className="rounded-2xl border border-white/[0.09] bg-white/[0.025] p-6"><p className="font-mono text-[10px] uppercase tracking-[0.2em] text-white/30">Build status</p><div className="mt-7 grid place-items-center rounded-xl border border-dashed border-white/10 bg-black/10 py-9 text-center"><div className="grid h-12 w-12 place-items-center rounded-full border border-white/10 text-white/25"><Download className="h-5 w-5" /></div><p className="mt-4 text-sm text-white/50">No artifact yet</p><p className="mt-2 max-w-[220px] text-xs leading-5 text-white/30">Android worker and signing credentials are required before a download becomes available.</p></div><div className="mt-6 space-y-3"><ChecklistRow label="Web bundle" state="ready" /><ChecklistRow label="Android worker" state="pending" /><ChecklistRow label="Signing key" state="pending" /></div></div></div></>; }
